import{_ as s,c as a,d as p,o as t}from"./app-F_ELCBVL.js";const e={};function o(c,n){return t(),a("div",null,[...n[0]||(n[0]=[p(`<h1 id="rushwind-admin-—-update-mask-写面-字段级白名单、显式清除与点路径合并" tabindex="-1"><a class="header-anchor" href="#rushwind-admin-—-update-mask-写面-字段级白名单、显式清除与点路径合并"><span>RushWind Admin — update_mask 写面：字段级白名单、显式清除与点路径合并</span></a></h1><blockquote><p>本文回答一个问题：<strong>前端只改了一个昵称，后端凭什么保证其余几十个字段一个都不会被碰坏？「把某字段清空」和「没传这个字段」又怎么在同一个接口里区分？——拆解 update_mask 从契约字段到 SeaORM 赋值行的整条写面链路。</strong></p></blockquote><p><a href="https://github.com/tx7do/rushwind-admin" target="_blank" rel="noopener noreferrer">RushWind Admin</a> 的更新接口是同一个形状：请求体带一个 <code>id</code> 和一个大对象 <code>data</code>。麻烦全在细节里——管理后台的字段动辄几十个，一个&quot;只改昵称&quot;的表单提交，其余字段是原样回传的旧值；只要服务端照单全收，任何一个并发窗口里的旧快照都能把别人刚写进去的值覆盖回去。所以这条写面链路要回答的不是&quot;怎么更新&quot;，而是三个更细的动词：<strong>写（这个字段变了）、清（这个字段要置空）、不动（请求里根本没有它）</strong>。整提交语义只有前两个的混合体，区分不了&quot;清空&quot;和&quot;没传&quot;——这就是 <code>update_mask</code> 存在的理由。这批更新接口的集合，仓库文档称作<strong>写面</strong>（write face）：face 是契约驱动架构的既有词汇——同一份 proto 契约朝不同协议投影出 REST 面、gRPC 面、服务面，写面就是其中承载全部更新写路径的那一张，与查询侧相对。</p><hr><h2 id="一、契约面-掩码是请求消息的第-3-号字段" tabindex="-1"><a class="header-anchor" href="#一、契约面-掩码是请求消息的第-3-号字段"><span>一、契约面：掩码是请求消息的第 3 号字段</span></a></h2><p>掩码不是文档约定，是契约字段。每个 Update 请求消息按 AIP-134 的形状声明它：</p><div class="language-protobuf line-numbers-mode" data-highlighter="prismjs" data-ext="protobuf"><pre><code><span class="line"><span class="token comment">// backend/apps/admin/api/protos/bi/service/v1/bi_dashboard.proto</span></span>
<span class="line"><span class="token keyword">message</span> <span class="token class-name">UpdateBiDashboardRequest</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token builtin">uint64</span> id <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token positional-class-name class-name">BiDashboard</span> data <span class="token operator">=</span> <span class="token number">2</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token positional-class-name class-name">google<span class="token punctuation">.</span>protobuf<span class="token punctuation">.</span>FieldMask</span> update_mask <span class="token operator">=</span> <span class="token number">3</span> <span class="token punctuation">[</span></span>
<span class="line">    <span class="token annotation">json_name</span> <span class="token operator">=</span> <span class="token string">&quot;updateMask&quot;</span></span>
<span class="line">    <span class="token comment">// ……openapi 属性注解略</span></span>
<span class="line">  <span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token comment">// 要更新的字段列表</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>客户端两种送法都被绑定层吃下：JSON body 里的 <code>&quot;updateMask&quot;: [&quot;name&quot;,&quot;path&quot;]</code>，或表单 query 里的 <code>updateMask=name,path</code>。后者要在绑定层做一次归一化——逗号切分、camelCase 转 snake_case。这不是可做可不做的礼貌，是线上契约的一部分，有测试钉着：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/apps/admin/tests/binder.rs</span></span>
<span class="line"><span class="token attribute attr-name">#[test]</span></span>
<span class="line"><span class="token keyword">fn</span> <span class="token function-definition function">field_mask_json_name_snake_normalization</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">let</span> <span class="token keyword">mut</span> m <span class="token operator">=</span> <span class="token function">fresh</span><span class="token punctuation">(</span><span class="token string">&quot;dict.service.v1.UpdateLanguageRequest&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">bind_form</span><span class="token punctuation">(</span><span class="token operator">&amp;</span><span class="token keyword">mut</span> m<span class="token punctuation">,</span> <span class="token operator">&amp;</span><span class="token punctuation">[</span><span class="token punctuation">(</span><span class="token string">&quot;updateMask&quot;</span><span class="token punctuation">.</span><span class="token function">into</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token macro property">vec!</span><span class="token punctuation">[</span><span class="token string">&quot;aB,cD_e&quot;</span><span class="token punctuation">.</span><span class="token function">into</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">unwrap</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">let</span> out<span class="token punctuation">:</span> <span class="token namespace">admin<span class="token punctuation">::</span>proto<span class="token punctuation">::</span>dict<span class="token punctuation">::</span>service<span class="token punctuation">::</span>v1<span class="token punctuation">::</span></span><span class="token class-name">UpdateLanguageRequest</span> <span class="token operator">=</span> m<span class="token punctuation">.</span><span class="token function">transcode_to</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">unwrap</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">let</span> mask <span class="token operator">=</span> out<span class="token punctuation">.</span>update_mask<span class="token punctuation">.</span><span class="token function">expect</span><span class="token punctuation">(</span><span class="token string">&quot;mask set&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span>paths<span class="token punctuation">;</span></span>
<span class="line">    <span class="token macro property">assert_eq!</span><span class="token punctuation">(</span>mask<span class="token punctuation">,</span> <span class="token operator">&amp;</span><span class="token punctuation">[</span><span class="token string">&quot;a_b&quot;</span><span class="token punctuation">.</span><span class="token function">to_string</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token string">&quot;c_d_e&quot;</span><span class="token punctuation">.</span><span class="token function">to_string</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>&quot;aB,cD_e&quot;</code> 进来，<code>[&quot;a_b&quot;, &quot;c_d_e&quot;]</code> 出去。归一化规则只有一条：<strong>去掉下划线、转小写后比较</strong>——<code>homePath</code>、<code>home_path</code>、<code>HomePath</code> 是同一个字段。</p><h2 id="二、掩码的三原语" tabindex="-1"><a class="header-anchor" href="#二、掩码的三原语"><span>二、掩码的三原语</span></a></h2><p>掩码的运行时形态是一个 85 行的小类型。核心不是结构，是三个判断函数——门的所有行为都由它们组合出来：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/apps/admin/src/admin/fieldmask.rs</span></span>
<span class="line"><span class="token comment">/// 字段是否被掩码选中。无掩码恒真；点路径按顶层段算选中</span></span>
<span class="line"><span class="token comment">/// （\`meta.title\` 选中 \`meta\` 域）。收 snake 或 camel 列名。</span></span>
<span class="line"><span class="token keyword">pub</span><span class="token punctuation">(</span><span class="token keyword">crate</span><span class="token punctuation">)</span> <span class="token keyword">fn</span> <span class="token function-definition function">touches</span><span class="token punctuation">(</span><span class="token operator">&amp;</span><span class="token keyword">self</span><span class="token punctuation">,</span> field<span class="token punctuation">:</span> <span class="token operator">&amp;</span><span class="token keyword">str</span><span class="token punctuation">)</span> <span class="token punctuation">-&gt;</span> <span class="token keyword">bool</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">match</span> <span class="token operator">&amp;</span><span class="token keyword">self</span><span class="token punctuation">.</span>paths <span class="token punctuation">{</span></span>
<span class="line">        <span class="token class-name">None</span> <span class="token operator">=&gt;</span> <span class="token boolean">true</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token class-name">Some</span><span class="token punctuation">(</span>set<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">let</span> want <span class="token operator">=</span> <span class="token function">normalize</span><span class="token punctuation">(</span>field<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            set<span class="token punctuation">.</span><span class="token function">iter</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">any</span><span class="token punctuation">(</span><span class="token closure-params"><span class="token closure-punctuation punctuation">|</span>p<span class="token closure-punctuation punctuation">|</span></span> p<span class="token punctuation">.</span><span class="token function">split</span><span class="token punctuation">(</span><span class="token char">&#39;.&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">next</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">unwrap_or</span><span class="token punctuation">(</span>p<span class="token punctuation">)</span> <span class="token operator">==</span> want<span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">/// 字段的&quot;整个域&quot;是否被字面选中（无掩码真；\`meta.title\` 只选子段，</span></span>
<span class="line"><span class="token comment">/// 不算选中整个 \`meta\`）。载荷 None 时只有 selected-whole 才显式清列</span></span>
<span class="line"><span class="token comment">/// ——仅点路径选中 + 载荷缺 = &quot;未携带&quot;，列原样留给合并域。</span></span>
<span class="line"><span class="token keyword">pub</span><span class="token punctuation">(</span><span class="token keyword">crate</span><span class="token punctuation">)</span> <span class="token keyword">fn</span> <span class="token function-definition function">selects_whole</span><span class="token punctuation">(</span><span class="token operator">&amp;</span><span class="token keyword">self</span><span class="token punctuation">,</span> field<span class="token punctuation">:</span> <span class="token operator">&amp;</span><span class="token keyword">str</span><span class="token punctuation">)</span> <span class="token punctuation">-&gt;</span> <span class="token keyword">bool</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">match</span> <span class="token operator">&amp;</span><span class="token keyword">self</span><span class="token punctuation">.</span>paths <span class="token punctuation">{</span></span>
<span class="line">        <span class="token class-name">None</span> <span class="token operator">=&gt;</span> <span class="token boolean">true</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token class-name">Some</span><span class="token punctuation">(</span>set<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> set<span class="token punctuation">.</span><span class="token function">contains</span><span class="token punctuation">(</span><span class="token operator">&amp;</span><span class="token function">normalize</span><span class="token punctuation">(</span>field<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">fn</span> <span class="token function-definition function">normalize</span><span class="token punctuation">(</span>field<span class="token punctuation">:</span> <span class="token operator">&amp;</span><span class="token keyword">str</span><span class="token punctuation">)</span> <span class="token punctuation">-&gt;</span> <span class="token class-name">String</span> <span class="token punctuation">{</span></span>
<span class="line">    field<span class="token punctuation">.</span><span class="token function">trim</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">replace</span><span class="token punctuation">(</span><span class="token char">&#39;_&#39;</span><span class="token punctuation">,</span> <span class="token string">&quot;&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">to_ascii_lowercase</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>三个原语各自的职责：</p><ul><li><strong><code>touches</code></strong>：进门判断。掩码选中才允许碰这一列，白名单的本体；</li><li><strong><code>selects_whole</code></strong>：整域判断。<code>meta.title</code> 算&quot;选中 meta 域&quot;（能进门），但不算&quot;字面写了 meta&quot;（不能整列清空）——这个区分是 jsonb 域特殊形式的全部依据；</li><li><strong><code>unrestricted</code></strong>：无掩码判断。<code>paths</code> 为 <code>None</code> 即全量提交语义。</li></ul><p>最容易被忽略的是第四种输入：<strong>掩码在场但为空集</strong>。AIP-134 的严格读法是&quot;什么都不许动&quot;——前端表单零键时送出的空串掩码，不该被当成&quot;全放行&quot;：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/apps/admin/src/admin/fieldmask.rs</span></span>
<span class="line"><span class="token comment">/// present-but-empty = 什么都不许动（AIP-134 严格读法）：前端表单</span></span>
<span class="line"><span class="token comment">/// 零键时送出的空串掩码不该被当成&quot;全放行&quot;。</span></span>
<span class="line"><span class="token attribute attr-name">#[test]</span></span>
<span class="line"><span class="token keyword">fn</span> <span class="token function-definition function">present_empty_mask_admits_nothing</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">let</span> m <span class="token operator">=</span> <span class="token function">mask</span><span class="token punctuation">(</span><span class="token operator">&amp;</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token macro property">assert!</span><span class="token punctuation">(</span><span class="token operator">!</span>m<span class="token punctuation">.</span><span class="token function">unrestricted</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token macro property">assert!</span><span class="token punctuation">(</span><span class="token operator">!</span>m<span class="token punctuation">.</span><span class="token function">touches</span><span class="token punctuation">(</span><span class="token string">&quot;name&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token macro property">assert!</span><span class="token punctuation">(</span><span class="token operator">!</span>m<span class="token punctuation">.</span><span class="token function">selects_whole</span><span class="token punctuation">(</span><span class="token string">&quot;name&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>四种输入、三种语义，一张表摆平：</p><table><thead><tr><th>掩码形态</th><th>语义</th></tr></thead><tbody><tr><td>缺席（<code>None</code>）</td><td>全量提交：与历史无掩码行为逐字节等价</td></tr><tr><td>空集</td><td>什么都不许动（present-but-empty 严格读法）</td></tr><tr><td>顶层字段名</td><td>该字段可写（含显式清除）</td></tr><tr><td>点路径（<code>meta.title</code>）</td><td>子段可写，整列不可清，合并域接管</td></tr></tbody></table><h2 id="三、set-masked-把三通道写进每一行赋值" tabindex="-1"><a class="header-anchor" href="#三、set-masked-把三通道写进每一行赋值"><span>三、set_masked!：把三通道写进每一行赋值</span></a></h2><p>门判断有了，落点在哪？答案是一个宏。全仓 update 写面的每一行字段赋值都经它发出，三种通道在宏里定型：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/apps/admin/src/admin/macros.rs</span></span>
<span class="line"><span class="token punctuation">(</span>opt_named <span class="token variable">$mask</span><span class="token punctuation">:</span><span class="token fragment-specifier punctuation">expr</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">:</span><span class="token fragment-specifier punctuation">expr</span><span class="token punctuation">,</span> <span class="token variable">$field</span><span class="token punctuation">:</span><span class="token fragment-specifier punctuation">ident</span><span class="token punctuation">,</span> <span class="token variable">$name</span><span class="token punctuation">:</span><span class="token fragment-specifier punctuation">expr</span><span class="token punctuation">,</span> <span class="token variable">$value</span><span class="token punctuation">:</span><span class="token fragment-specifier punctuation">expr</span><span class="token punctuation">,</span> <span class="token variable">$map</span><span class="token punctuation">:</span><span class="token fragment-specifier punctuation">expr</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token variable">$mask</span><span class="token punctuation">.</span><span class="token function">touches</span><span class="token punctuation">(</span><span class="token variable">$name</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">match</span> <span class="token operator">&amp;</span><span class="token variable">$value</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token class-name">Some</span><span class="token punctuation">(</span>v<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token variable">$model</span><span class="token punctuation">.</span><span class="token variable">$field</span> <span class="token operator">=</span> <span class="token namespace">sea_orm<span class="token punctuation">::</span></span><span class="token class-name">Set</span><span class="token punctuation">(</span><span class="token variable">$map</span><span class="token punctuation">(</span>v<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">            <span class="token class-name">None</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">                <span class="token keyword">if</span> <span class="token operator">!</span><span class="token variable">$mask</span><span class="token punctuation">.</span><span class="token function">unrestricted</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                    <span class="token variable">$model</span><span class="token punctuation">.</span><span class="token variable">$field</span> <span class="token operator">=</span> <span class="token namespace">sea_orm<span class="token punctuation">::</span></span><span class="token class-name">Set</span><span class="token punctuation">(</span><span class="token class-name">None</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">                <span class="token punctuation">}</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">(</span>req_named <span class="token variable">$mask</span><span class="token punctuation">:</span><span class="token fragment-specifier punctuation">expr</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">:</span><span class="token fragment-specifier punctuation">expr</span><span class="token punctuation">,</span> <span class="token variable">$field</span><span class="token punctuation">:</span><span class="token fragment-specifier punctuation">ident</span><span class="token punctuation">,</span> <span class="token variable">$name</span><span class="token punctuation">:</span><span class="token fragment-specifier punctuation">expr</span><span class="token punctuation">,</span> <span class="token variable">$value</span><span class="token punctuation">:</span><span class="token fragment-specifier punctuation">expr</span><span class="token punctuation">,</span> <span class="token variable">$map</span><span class="token punctuation">:</span><span class="token fragment-specifier punctuation">expr</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token variable">$mask</span><span class="token punctuation">.</span><span class="token function">touches</span><span class="token punctuation">(</span><span class="token variable">$name</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token keyword">let</span> <span class="token class-name">Some</span><span class="token punctuation">(</span>v<span class="token punctuation">)</span> <span class="token operator">=</span> <span class="token operator">&amp;</span><span class="token variable">$value</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token variable">$model</span><span class="token punctuation">.</span><span class="token variable">$field</span> <span class="token operator">=</span> <span class="token namespace">sea_orm<span class="token punctuation">::</span></span><span class="token class-name">Set</span><span class="token punctuation">(</span><span class="token variable">$map</span><span class="token punctuation">(</span>v<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>opt</code> 形态给可空列，三条通道：</p><ol><li><strong>掩码选中 + 载荷 <code>Some</code></strong> → 写值；</li><li><strong>掩码选中 + 载荷 <code>None</code></strong> → 显式 <code>Set(None)</code> 清列——这就是&quot;清空&quot;动词的落点，整提交语义永远表达不了的那个；</li><li><strong>无掩码 + 载荷 <code>None</code></strong> → 什么都不做。存量全量提交语义原封不动：老客户端不带掩码提交，行为与从前逐字节一致。</li></ol><p><code>req</code> 形态给 NOT NULL 列：没有&quot;清成 NULL&quot;的语义可表达，所以只有写值通道，<code>None</code> 永不落笔。</p><p>create / sync 这类非 PATCH 入口复用同一条 apply 链，传的是显式无掩码：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/apps/admin/src/admin/fieldmask.rs</span></span>
<span class="line"><span class="token comment">/// 显式无掩码——create/sync 等非 PATCH 入口复用 apply 链时用。</span></span>
<span class="line"><span class="token keyword">pub</span><span class="token punctuation">(</span><span class="token keyword">crate</span><span class="token punctuation">)</span> <span class="token keyword">fn</span> <span class="token function-definition function">unmasked</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">-&gt;</span> <span class="token keyword">Self</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">Self</span> <span class="token punctuation">{</span> paths<span class="token punctuation">:</span> <span class="token class-name">None</span> <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/apps/admin/src/admin/services/menu.rs</span></span>
<span class="line"><span class="token keyword">Self</span><span class="token punctuation">::</span><span class="token function">apply_fields</span><span class="token punctuation">(</span><span class="token operator">&amp;</span><span class="token keyword">mut</span> a<span class="token punctuation">,</span> <span class="token operator">&amp;</span>data<span class="token punctuation">,</span> <span class="token operator">&amp;</span><span class="token keyword">crate</span><span class="token module-declaration namespace"><span class="token punctuation">::</span>fieldmask<span class="token punctuation">::</span></span><span class="token class-name">FieldMask</span><span class="token punctuation">::</span><span class="token function">unmasked</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>无掩码时 <code>touches</code> 恒真、<code>unrestricted</code> 为真 → <code>opt</code> 形态的 None 分支被短路——create 的行为与旧 if-let-Some 逐字节一致。<strong>同一套赋值代码服务两种语义，切换点收敛在一个参数上</strong>，这是全仓 12 处 create/sync 入口敢复用 apply 链的底气。</p><h2 id="四、jsonb-域的特殊形式-点路径合并" tabindex="-1"><a class="header-anchor" href="#四、jsonb-域的特殊形式-点路径合并"><span>四、jsonb 域的特殊形式：点路径合并</span></a></h2><p>标量列的门到宏为止。jsonb 列多出一层问题：<code>meta</code> 是一个 JSON 域（图标、标题、keepAlive……），客户端只想改图标时，送 <code>updateMask=meta.icon</code> 加一个只带 icon 的载荷——整列替换会把其余键全部抹掉。</p><p>menu 的 <code>apply_fields</code> 先在门内给 meta 一个特判：点路径选中不算整域选中，载荷缺 meta 不是&quot;清列&quot;信号，而是&quot;交给合并域&quot;：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/apps/admin/src/admin/services/menu.rs</span></span>
<span class="line"><span class="token comment">// meta 不走 opt 清列形态：掩码只选中点路径子段（meta.title）时</span></span>
<span class="line"><span class="token comment">// touches(&quot;meta&quot;) 为真但 selects_whole 为假——载荷缺 meta 是</span></span>
<span class="line"><span class="token comment">// &quot;未携带&quot;（列原样，合并域接管），只有整域选中/无掩码的 None</span></span>
<span class="line"><span class="token comment">// 才显式清列。</span></span>
<span class="line"><span class="token keyword">if</span> mask<span class="token punctuation">.</span><span class="token function">touches</span><span class="token punctuation">(</span><span class="token string">&quot;meta&quot;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">match</span> <span class="token operator">&amp;</span>data<span class="token punctuation">.</span>meta <span class="token punctuation">{</span></span>
<span class="line">        <span class="token class-name">Some</span><span class="token punctuation">(</span>m<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> a<span class="token punctuation">.</span>meta <span class="token operator">=</span> <span class="token class-name">Set</span><span class="token punctuation">(</span><span class="token class-name">Some</span><span class="token punctuation">(</span><span class="token function">menu_meta_to_json</span><span class="token punctuation">(</span>m<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token class-name">None</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">if</span> mask<span class="token punctuation">.</span><span class="token function">selects_whole</span><span class="token punctuation">(</span><span class="token string">&quot;meta&quot;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                a<span class="token punctuation">.</span>meta <span class="token operator">=</span> <span class="token class-name">Set</span><span class="token punctuation">(</span><span class="token class-name">None</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>update 侧抽取 <code>meta.</code> 前缀的叶子，交给合并函数：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/apps/admin/src/admin/services/menu.rs</span></span>
<span class="line"><span class="token comment">/// update_mask 点路径选中的 meta 子字段合并进存量 jsonb：</span></span>
<span class="line"><span class="token comment">/// 选中且有值 → 写值；选中但为空 → 显式写 json null（清空</span></span>
<span class="line"><span class="token comment">/// 图标/标题不留残值）；未选中的键 → 存量原样保留。base 为 NULL 列时从</span></span>
<span class="line"><span class="token comment">/// \`{}\` 起步——应用层合并天然免疫 SQL \`NULL || x\` 静默丢失。</span></span>
<span class="line"><span class="token keyword">fn</span> <span class="token function-definition function">merge_meta_fields</span><span class="token punctuation">(</span></span>
<span class="line">    base<span class="token punctuation">:</span> <span class="token namespace">serde_json<span class="token punctuation">::</span></span><span class="token class-name">Value</span><span class="token punctuation">,</span></span>
<span class="line">    meta<span class="token punctuation">:</span> <span class="token operator">&amp;</span><span class="token keyword">crate</span><span class="token module-declaration namespace"><span class="token punctuation">::</span>proto<span class="token punctuation">::</span>permission<span class="token punctuation">::</span>service<span class="token punctuation">::</span>v1<span class="token punctuation">::</span></span><span class="token class-name">MenuMeta</span><span class="token punctuation">,</span></span>
<span class="line">    leaves<span class="token punctuation">:</span> <span class="token operator">&amp;</span><span class="token punctuation">[</span><span class="token operator">&amp;</span><span class="token keyword">str</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span> <span class="token punctuation">-&gt;</span> <span class="token namespace">serde_json<span class="token punctuation">::</span></span><span class="token class-name">Value</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">let</span> <span class="token keyword">mut</span> obj <span class="token operator">=</span> <span class="token keyword">match</span> base <span class="token punctuation">{</span></span>
<span class="line">        <span class="token namespace">serde_json<span class="token punctuation">::</span></span><span class="token class-name">Value</span><span class="token punctuation">::</span><span class="token class-name">Object</span><span class="token punctuation">(</span>map<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> map<span class="token punctuation">,</span></span>
<span class="line">        _ <span class="token operator">=&gt;</span> <span class="token namespace">serde_json<span class="token punctuation">::</span></span><span class="token class-name">Map</span><span class="token punctuation">::</span><span class="token function">new</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">let</span> converted <span class="token operator">=</span> <span class="token function">menu_meta_to_json</span><span class="token punctuation">(</span>meta<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">for</span> leaf <span class="token keyword">in</span> leaves <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">let</span> <span class="token class-name">Some</span><span class="token punctuation">(</span>key<span class="token punctuation">)</span> <span class="token operator">=</span> <span class="token function">meta_field_json_key</span><span class="token punctuation">(</span>leaf<span class="token punctuation">)</span> <span class="token keyword">else</span> <span class="token punctuation">{</span> <span class="token keyword">continue</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">let</span> value <span class="token operator">=</span> converted<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span>key<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">cloned</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">unwrap_or</span><span class="token punctuation">(</span><span class="token namespace">serde_json<span class="token punctuation">::</span></span><span class="token class-name">Value</span><span class="token punctuation">::</span><span class="token class-name">Null</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        obj<span class="token punctuation">.</span><span class="token function">insert</span><span class="token punctuation">(</span>key<span class="token punctuation">.</span><span class="token function">to_string</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> value<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token namespace">serde_json<span class="token punctuation">::</span></span><span class="token class-name">Value</span><span class="token punctuation">::</span><span class="token class-name">Object</span><span class="token punctuation">(</span>obj<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>三条合并规则，每条都有数据库级 round-trip 测试压着：</p><p><strong>未选中的键存活</strong>——掩码只有 <code>meta.icon</code>，<code>title</code> 原样不动：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/apps/admin/src/admin/services/menu.rs（测试截取）</span></span>
<span class="line">svc<span class="token punctuation">.</span><span class="token function">update</span><span class="token punctuation">(</span>me<span class="token punctuation">,</span> <span class="token function">update_req</span><span class="token punctuation">(</span>row<span class="token punctuation">.</span>id <span class="token keyword">as</span> <span class="token keyword">u64</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token class-name">Menu</span> <span class="token punctuation">{</span> meta<span class="token punctuation">:</span> <span class="token class-name">Some</span><span class="token punctuation">(</span><span class="token class-name">MenuMeta</span> <span class="token punctuation">{</span> icon<span class="token punctuation">:</span> <span class="token class-name">Some</span><span class="token punctuation">(</span><span class="token string">&quot;lucide:layout-dashboard&quot;</span><span class="token punctuation">.</span><span class="token function">into</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token punctuation">..</span><span class="token class-name">Default</span><span class="token punctuation">::</span><span class="token function">default</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token punctuation">..</span><span class="token class-name">Default</span><span class="token punctuation">::</span><span class="token function">default</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token operator">&amp;</span><span class="token punctuation">[</span><span class="token string">&quot;meta.icon&quot;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token keyword">await</span><span class="token punctuation">.</span><span class="token function">unwrap</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token macro property">assert_eq!</span><span class="token punctuation">(</span>meta<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&quot;icon&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">and_then</span><span class="token punctuation">(</span><span class="token closure-params"><span class="token closure-punctuation punctuation">|</span>v<span class="token closure-punctuation punctuation">|</span></span> v<span class="token punctuation">.</span><span class="token function">as_str</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token class-name">Some</span><span class="token punctuation">(</span><span class="token string">&quot;lucide:layout-dashboard&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token string">&quot;masked leaf updated&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token macro property">assert_eq!</span><span class="token punctuation">(</span>meta<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&quot;title&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">and_then</span><span class="token punctuation">(</span><span class="token closure-params"><span class="token closure-punctuation punctuation">|</span>v<span class="token closure-punctuation punctuation">|</span></span> v<span class="token punctuation">.</span><span class="token function">as_str</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token class-name">Some</span><span class="token punctuation">(</span><span class="token string">&quot;仪表盘&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token string">&quot;unmasked title survives the merge&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>选中但为空 → 显式 null</strong>——清空图标不留残值，读回 proto 时收敛为 <code>None</code>；<strong>门本身</strong>——载荷夹带了掩码外的字段，落不了地：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/apps/admin/src/admin/services/menu.rs（测试截取）</span></span>
<span class="line"><span class="token keyword">async</span> <span class="token keyword">fn</span> <span class="token function-definition function">mask_gates_unlisted_scalar_fields</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 载荷带 path: Some(&quot;/evil&quot;)，掩码只有 [&quot;name&quot;]</span></span>
<span class="line">    <span class="token macro property">assert_eq!</span><span class="token punctuation">(</span>fresh<span class="token punctuation">.</span>name<span class="token punctuation">,</span> <span class="token string">&quot;工作台&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;masked field lands&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token macro property">assert_eq!</span><span class="token punctuation">(</span>fresh<span class="token punctuation">.</span>path<span class="token punctuation">.</span><span class="token function">as_deref</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token class-name">Some</span><span class="token punctuation">(</span><span class="token string">&quot;/dashboard&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">&quot;unmasked path is not writable through the gate&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="五、门不管的-特殊逻辑的归属" tabindex="-1"><a class="header-anchor" href="#五、门不管的-特殊逻辑的归属"><span>五、门不管的：特殊逻辑的归属</span></a></h2><p>字段门只管&quot;载荷字段 → 列&quot;的写面，不接管一切。哪些特殊逻辑留在门外、哪些跟着掩码走，<code>docs/binding-spec.md</code> §2.5 有一句成文的原则：</p><blockquote><p><strong>特殊逻辑门控原则</strong>：校验类逻辑原位保留（门只管&quot;载荷字段 → 列&quot;的写面）；与&quot;字段是否被写&quot;耦合的副作用按掩码门控。</p></blockquote><p>两类各看一例。<strong>校验原位保留</strong>：AI Agent 的图结构校验仍在写前执行——但只在掩码选中 <code>graph</code> 时才触发；不更新图就不做图校验，校验拒绝时旧列原样：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/apps/admin/src/admin/services/ai_agent.rs</span></span>
<span class="line"><span class="token keyword">if</span> mask<span class="token punctuation">.</span><span class="token function">touches</span><span class="token punctuation">(</span><span class="token string">&quot;graph&quot;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token keyword">let</span> <span class="token class-name">Some</span><span class="token punctuation">(</span>v<span class="token punctuation">)</span> <span class="token operator">=</span> <span class="token operator">&amp;</span>data<span class="token punctuation">.</span>graph <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// 图非空时必须能解析且过静态校验（写前拒绝，不清残列）。</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token operator">!</span>v<span class="token punctuation">.</span><span class="token function">trim</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">is_empty</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">let</span> g <span class="token operator">=</span> <span class="token namespace">agent_graph<span class="token punctuation">::</span></span><span class="token function">parse_agent_graph</span><span class="token punctuation">(</span>v<span class="token punctuation">)</span></span>
<span class="line">                <span class="token punctuation">.</span><span class="token function">map_err</span><span class="token punctuation">(</span><span class="token closure-params"><span class="token closure-punctuation punctuation">|</span>e<span class="token closure-punctuation punctuation">|</span></span> <span class="token function">status_error</span><span class="token punctuation">(</span><span class="token string">&quot;BAD_REQUEST&quot;</span><span class="token punctuation">,</span> e<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token operator">?</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token namespace">agent_graph<span class="token punctuation">::</span></span><span class="token function">validate_agent_graph</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>g<span class="token punctuation">)</span></span>
<span class="line">                <span class="token punctuation">.</span><span class="token function">map_err</span><span class="token punctuation">(</span><span class="token closure-params"><span class="token closure-punctuation punctuation">|</span>e<span class="token closure-punctuation punctuation">|</span></span> <span class="token function">status_error</span><span class="token punctuation">(</span><span class="token string">&quot;BAD_REQUEST&quot;</span><span class="token punctuation">,</span> e<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token operator">?</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"><span class="token keyword">crate</span><span class="token module-declaration namespace"><span class="token punctuation">::</span>set_masked</span><span class="token operator">!</span><span class="token punctuation">(</span>opt mask<span class="token punctuation">,</span> a<span class="token punctuation">,</span> graph<span class="token punctuation">,</span> data<span class="token punctuation">.</span>graph<span class="token punctuation">,</span> <span class="token closure-params"><span class="token closure-punctuation punctuation">|</span>v<span class="token punctuation">:</span> <span class="token operator">&amp;</span><span class="token class-name">String</span><span class="token closure-punctuation punctuation">|</span></span> <span class="token class-name">Some</span><span class="token punctuation">(</span>v<span class="token punctuation">.</span><span class="token function">clone</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>门外恒执行</strong>：BI 仪表盘的乐观锁 CAS 与版本自增是 handler 自己的职责，与掩码无关——哪怕掩码只选了 <code>name</code>，版本冲突照样拒绝、版本号照样 +1：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/apps/admin/src/admin/services/bi_dashboard.rs</span></span>
<span class="line"><span class="token comment">// 乐观锁：data.version 回传读到的版本时按 CAS 校验，冲突 BadRequest；</span></span>
<span class="line"><span class="token comment">// 版本号无论走哪条路都 +1。</span></span>
<span class="line"><span class="token keyword">if</span> <span class="token keyword">let</span> <span class="token class-name">Some</span><span class="token punctuation">(</span>want<span class="token punctuation">)</span> <span class="token operator">=</span> data<span class="token punctuation">.</span>version <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> row<span class="token punctuation">.</span>version<span class="token punctuation">.</span><span class="token function">unwrap_or</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span> <span class="token operator">!=</span> want <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token class-name">Err</span><span class="token punctuation">(</span><span class="token function">status_error</span><span class="token punctuation">(</span><span class="token string">&quot;BAD_REQUEST&quot;</span><span class="token punctuation">,</span></span>
<span class="line">            <span class="token macro property">format!</span><span class="token punctuation">(</span><span class="token string">&quot;dashboard version conflict: expected {}, got {}&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">...</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"><span class="token keyword">let</span> mask <span class="token operator">=</span> <span class="token keyword">crate</span><span class="token module-declaration namespace"><span class="token punctuation">::</span>fieldmask<span class="token punctuation">::</span></span><span class="token class-name">FieldMask</span><span class="token punctuation">::</span><span class="token function">from</span><span class="token punctuation">(</span>req<span class="token punctuation">.</span>update_mask<span class="token punctuation">.</span><span class="token function">as_ref</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token function">apply_fields</span><span class="token punctuation">(</span><span class="token operator">&amp;</span><span class="token keyword">mut</span> a<span class="token punctuation">,</span> <span class="token operator">&amp;</span>data<span class="token punctuation">,</span> <span class="token operator">&amp;</span>mask<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">crate</span><span class="token module-declaration namespace"><span class="token punctuation">::</span>stamp_update</span><span class="token operator">!</span><span class="token punctuation">(</span>a<span class="token punctuation">,</span> payload<span class="token punctuation">.</span>user_id<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">a<span class="token punctuation">.</span>version <span class="token operator">=</span> <span class="token class-name">Set</span><span class="token punctuation">(</span><span class="token class-name">Some</span><span class="token punctuation">(</span>a<span class="token punctuation">.</span>version<span class="token punctuation">.</span><span class="token function">clone</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">unwrap</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">unwrap_or</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span> <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>还有一类是<strong>晚落的列的补位</strong>：角色的 <code>home_path</code>（按角色设定默认首页）落在掩码机制之后，用映射函数把 <code>Some(空串)</code> 翻译成 <code>None</code>，走清列通道——空串清除、缺省不动，与旧 if-let-Some 语义对齐：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/apps/admin/src/admin/services/role.rs</span></span>
<span class="line"><span class="token keyword">crate</span><span class="token module-declaration namespace"><span class="token punctuation">::</span>set_masked</span><span class="token operator">!</span><span class="token punctuation">(</span>opt mask<span class="token punctuation">,</span> a<span class="token punctuation">,</span> home_path<span class="token punctuation">,</span> data<span class="token punctuation">.</span>home_path<span class="token punctuation">,</span> <span class="token closure-params"><span class="token closure-punctuation punctuation">|</span>v<span class="token punctuation">:</span> <span class="token operator">&amp;</span><span class="token class-name">String</span><span class="token closure-punctuation punctuation">|</span></span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> v<span class="token punctuation">.</span><span class="token function">is_empty</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token class-name">None</span> <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span> <span class="token class-name">Some</span><span class="token punctuation">(</span>v<span class="token punctuation">.</span><span class="token function">clone</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>门控调用点全仓 32 处、分布在 30 个服务文件，<code>set_masked!</code> 调用行 214 行——一个中型系统的整个写面，就是这一张白名单表的展开。</p><h2 id="六、失败模式-当门没落地" tabindex="-1"><a class="header-anchor" href="#六、失败模式-当门没落地"><span>六、失败模式：当门没落地</span></a></h2><p>这套语义交过一次真金白银的学费。曾经有一段时期，<strong>契约在说 update_mask，前端在发 update_mask，OpenAPI 在写 update_mask，发版说明在吹 update_mask——而服务端把每一次掩码都忽略成整提交</strong>。起因不是设计缺陷，是一次大规模合并的解决方式：旧布局路径被新布局的删除回答了，整个写面被静默回退，而契约、绑定层、规格、五套前端全都还在广告这个语义。</p><p>这类事故的可怕之处在于<strong>完全静默</strong>：接口不报错、测试大多还绿（它们提交的是全量数据）、用户得到的是&quot;偶发的字段互相覆盖&quot;。它暴露的不是某个 bug，而是一条工程铁律——<strong>广告了的语义必须有独立于实现的守卫</strong>。现在的防线有三层：<code>FieldMask</code> 与归一化规则有纯逻辑测试（present-but-empty、camel 转 snake 各自钉死）；menu meta 有数据库级 round-trip 测试（合并、显式 null、门拦截各一）；binding-spec 把&quot;无掩码 = 与历史行为逐字节等价&quot;写成差分回归基准。门的可靠性不取决于实现它的那一天，取决于钉住它的那些测试。</p><h2 id="七、机制-×-关键决策-×-失败模式" tabindex="-1"><a class="header-anchor" href="#七、机制-×-关键决策-×-失败模式"><span>七、机制 × 关键决策 × 失败模式</span></a></h2><table><thead><tr><th>机制</th><th>关键决策</th><th>失败模式（若无此决策）</th></tr></thead><tbody><tr><td><code>touches</code> 白名单门</td><td>点路径按顶层段进门，掩码外字段不可写</td><td>并发旧快照覆盖他人写入，静默发生</td></tr><tr><td>显式清列通道</td><td>掩码选中 + <code>None</code> → <code>Set(None)</code>；无掩码 <code>None</code> 不动</td><td>&quot;清空&quot;不可表达，或无掩码行为被误改</td></tr><tr><td>present-but-empty 严格读法</td><td>空集掩码什么都不许动</td><td>空表单提交被当全放行，整行被零值洗掉</td></tr><tr><td>snake/camel 归一</td><td>去下划线小写比较，绑定层有归一化测试</td><td><code>homePath</code> 与 <code>home_path</code> 被当两个字段，门漏放</td></tr><tr><td><code>unmasked()</code> 复用 apply 链</td><td>create/sync 与 PATCH 共用赋值代码</td><td>两套赋值逻辑漂移，写面行为不一致</td></tr><tr><td>jsonb 点路径合并</td><td>整域选中才可清列；合并以存量 jsonb 为基线、<code>{}</code> 兜底</td><td>整列替换抹掉未选中键；SQL <code>NULL || x</code> 静默丢列</td></tr><tr><td>特殊逻辑门控原则</td><td>校验原位保留；CAS 等副作用门外恒执行</td><td>不更新图也触发图校验；掩码绕过版本冲突检查</td></tr><tr><td>守卫测试三层</td><td>纯逻辑 / 数据库 round-trip / 差分基准</td><td>门被合并静默回退，全量提交回归无人发现</td></tr></tbody></table><p>写面的一切复杂度，本质上是 <strong>PATCH 语义比 PUT 多出来的那一个动词</strong>。&quot;清空&quot;与&quot;没传&quot;的区分不可能靠约定俗成，只能靠一个显式的契约字段和一条从绑定层到赋值行的白名单链路。字段级更新做对了是隐形的——用户永远看不到它发力；做错了也是隐形的——直到某天两个管理员互相覆盖了对方的修改。</p><hr><p>项目地址：<a href="https://gitee.com/tx7do/rushwind-admin" target="_blank" rel="noopener noreferrer">Gitee</a> ｜ <a href="https://github.com/tx7do/rushwind-admin" target="_blank" rel="noopener noreferrer">GitHub</a></p><p>系列文章：</p><ul><li>上一篇：<a href="https://tx7do.github.io/posts/rushwind_admin_contract_driven.html" target="_blank" rel="noopener noreferrer">契约驱动：291 条路由零手写的工程化拆解</a></li><li>下一篇：<a href="https://tx7do.github.io/posts/rushwind_admin_tenant_recycle_bin.html" target="_blank" rel="noopener noreferrer">多租户行级隔离与租户回收站：Viewer 三态、repo_shell! 与全域级联清除</a></li></ul>`,60)])])}const i=s(e,[["render",o]]),u=JSON.parse('{"path":"/posts/rushwind_admin_update_mask.html","title":"RushWind Admin — update_mask 写面：字段级白名单、显式清除与点路径合并","lang":"zh-CN","frontmatter":{"date":"2026-11-20T00:00:00.000Z","category":["Rust编程"],"tag":["Rust","RushWind","Protobuf","API设计"],"sticky":10},"headers":[{"level":2,"title":"一、契约面：掩码是请求消息的第 3 号字段","slug":"一、契约面-掩码是请求消息的第-3-号字段","link":"#一、契约面-掩码是请求消息的第-3-号字段","children":[]},{"level":2,"title":"二、掩码的三原语","slug":"二、掩码的三原语","link":"#二、掩码的三原语","children":[]},{"level":2,"title":"三、set_masked!：把三通道写进每一行赋值","slug":"三、set-masked-把三通道写进每一行赋值","link":"#三、set-masked-把三通道写进每一行赋值","children":[]},{"level":2,"title":"四、jsonb 域的特殊形式：点路径合并","slug":"四、jsonb-域的特殊形式-点路径合并","link":"#四、jsonb-域的特殊形式-点路径合并","children":[]},{"level":2,"title":"五、门不管的：特殊逻辑的归属","slug":"五、门不管的-特殊逻辑的归属","link":"#五、门不管的-特殊逻辑的归属","children":[]},{"level":2,"title":"六、失败模式：当门没落地","slug":"六、失败模式-当门没落地","link":"#六、失败模式-当门没落地","children":[]},{"level":2,"title":"七、机制 × 关键决策 × 失败模式","slug":"七、机制-×-关键决策-×-失败模式","link":"#七、机制-×-关键决策-×-失败模式","children":[]}],"git":{"updatedTime":1795150321000,"contributors":[{"name":"Bobo","username":"Bobo","email":"yanglinbo@gmail.com","commits":2,"url":"https://github.com/Bobo"}],"changelog":[{"hash":"db72b04d7557f847e20325b35e03eff3e1a9bd4e","time":1795150321000,"email":"yanglinbo@gmail.com","author":"Bobo","message":"feat: update posts."},{"hash":"16d3c4973313d13612d77376cd8e8b96b7c18718","time":1795147039000,"email":"yanglinbo@gmail.com","author":"Bobo","message":"feat: add posts."}]},"filePathRelative":"posts/rushwind_admin_update_mask.md","excerpt":"\\n<blockquote>\\n<p>本文回答一个问题：<strong>前端只改了一个昵称，后端凭什么保证其余几十个字段一个都不会被碰坏？「把某字段清空」和「没传这个字段」又怎么在同一个接口里区分？——拆解 update_mask 从契约字段到 SeaORM 赋值行的整条写面链路。</strong></p>\\n</blockquote>\\n<p><a href=\\"https://github.com/tx7do/rushwind-admin\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">RushWind Admin</a> 的更新接口是同一个形状：请求体带一个 <code>id</code> 和一个大对象 <code>data</code>。麻烦全在细节里——管理后台的字段动辄几十个，一个\\"只改昵称\\"的表单提交，其余字段是原样回传的旧值；只要服务端照单全收，任何一个并发窗口里的旧快照都能把别人刚写进去的值覆盖回去。所以这条写面链路要回答的不是\\"怎么更新\\"，而是三个更细的动词：<strong>写（这个字段变了）、清（这个字段要置空）、不动（请求里根本没有它）</strong>。整提交语义只有前两个的混合体，区分不了\\"清空\\"和\\"没传\\"——这就是 <code>update_mask</code> 存在的理由。这批更新接口的集合，仓库文档称作<strong>写面</strong>（write face）：face 是契约驱动架构的既有词汇——同一份 proto 契约朝不同协议投影出 REST 面、gRPC 面、服务面，写面就是其中承载全部更新写路径的那一张，与查询侧相对。</p>"}');export{i as comp,u as data};
